// Alle enabled=1 Automatisierungen aus der DB laden.
// Ergebnis wird im nächsten Schritt mit den Bedingungen zusammengeführt.
const store = global.get('automationStore');
if (!store) {
    node.warn('automationStore nicht verfügbar – Runner übersprungen');
    return null;
}
msg.topic = store.buildEnabledListQuery();
return msg;

// Alle Bedingungen aller aktiven Automatisierungen in einem Abfrage laden.
// Die Automations-Rows werden im flow-context zwischengespeichert.
const store = global.get('automationStore');
if (!store) {
    return null;
}
const automationRows = Array.isArray(msg.payload) ? msg.payload : [];
if (automationRows.length === 0) {
    // Keine aktiven Automatisierungen – direkt fertig
    return null;
}
// Automations für den nächsten Schritt im flow-context merken
flow.set('runner_automations', automationRows);
msg.topic = store.buildAllConditionsForEnabledQuery();
return msg;

// Kernlogik des Runners:
//   1. Bedingungen pro Automatisierung aus den DB-Rows zusammenführen
//   2. shouldTrigger() aufrufen (Duplikatsschutz + Bedingungsprüfung)
//   3. Für jede ausgelöste Automatisierung commandMinimal aufrufen
//   4. MQTT-Befehle und Run-Ergebnisse getrennt ausgeben

const store = global.get('automationStore');
const engine = global.get('automationEngine');
const commandMinimal = global.get('commandMinimal');

if (!store || !engine || !commandMinimal) {
    node.warn('Mindestens ein Hilfsmodul fehlt (automationStore/automationEngine/commandMinimal)');
    return null;
}

// Aktive Automatisierungen aus flow-context laden (aus vorherigem Schritt).
const automationRows = flow.get('runner_automations') || [];
const conditionRows = Array.isArray(msg.payload) ? msg.payload : [];

// Bedingungen nach automation_id gruppieren (O(n) statt verschachtelter Schleifen).
const conditionsByAutomation = {};
conditionRows.forEach(function(c) {
    if (!conditionsByAutomation[c.automation_id]) {
        conditionsByAutomation[c.automation_id] = [];
    }
    conditionsByAutomation[c.automation_id].push(c);
});

// Duplikatsschutz-Map aus flow-context laden (Minutenschlüssel pro automation_id).
let lastRunMap = flow.get('runner_last_run_map') || {};

// smarthome_runtime enthält alle aktuellen Gerätezustände (wird von 20_device_store befüllt).
const runtime = global.get('smarthome_runtime') || { devices: {}, masters: {} };

const now = new Date();
const outMessages = [];
const resultStatements = [];

function merkeRunResult(automationId, resultText) {
    const sql = store.buildUpdateRunResultStatement(automationId, resultText);
    if (sql) {
        resultStatements.push(sql);
    }
}

automationRows.forEach(function(automation) {
    const conditions = conditionsByAutomation[automation.automation_id] || [];

    // Duplikatsschutz + alle Bedingungen prüfen.
    const triggerResult = engine.shouldTrigger(automation, conditions, {
        runtime: runtime,
        now: now,
        lastRunMap: lastRunMap
    });

    if (!triggerResult.trigger) {
        node.debug('Automatisierung ' + automation.automation_id + ' nicht ausgelöst: ' + triggerResult.reason);
        return;
    }

    // Ab hier gilt die Automation als Ausführungsversuch. Auch Fehler werden
    // in last_result geschrieben, damit die UI nicht schweigend veraltet bleibt.
    lastRunMap[automation.automation_id] = engine.currentMinuteKey(now);

    const actionInput = engine.buildActionInput(automation, runtime);
    if (!actionInput.ok) {
        const resultText = 'error: ' + actionInput.error;
        node.warn('Automatisierung ' + automation.automation_id + ': ' + actionInput.error);
        merkeRunResult(automation.automation_id, resultText);
        return;
    }

    // Befehl ausschliesslich über commandMinimal erzeugen – keine direkte MQTT-Payload-Erfindung.
    let commandResult;
    if (actionInput.actionKind === 'net_erl_relay_1') {
        commandResult = commandMinimal.buildNetErlRelay1Command(runtime, actionInput.commandInput);
    } else if (actionInput.actionKind === 'net_zrl_cover') {
        commandResult = commandMinimal.buildCoverCommand(runtime, actionInput.commandInput);
    } else {
        const resultText = 'error: unbekannte action_kind ' + actionInput.actionKind;
        node.warn(resultText);
        merkeRunResult(automation.automation_id, resultText);
        return;
    }

    if (!commandResult.ok) {
        const resultText = 'error: ' + (commandResult.error || commandResult.message || 'command_failed');
        node.warn('Automatisierung ' + automation.automation_id + ' – Befehlsfehler: ' + commandResult.message);
        merkeRunResult(automation.automation_id, resultText);
        return;
    }

    // MQTT-Nachricht für den mqtt out Node vorbereiten.
    outMessages.push({
        topic: commandResult.command.topic,
        payload: JSON.stringify(commandResult.command.payload),
        qos: 1,
        retain: false,
        _automationId: automation.automation_id
    });

    merkeRunResult(automation.automation_id, 'ok');
    node.log('Automatisierung ausgelöst: ' + automation.name + ' → ' + commandResult.command.topic);
});

// Aktualisierten Duplikatsschutz in flow-context zurückschreiben.
flow.set('runner_last_run_map', lastRunMap);

const resultMsg = resultStatements.length > 0
    ? { topic: ['BEGIN IMMEDIATE;', ...resultStatements, 'COMMIT;'].join('\n') }
    : null;

// Output 1: mehrere MQTT-Nachrichten auf einem Ausgang als Array.
// Output 2: ein SQLite-Batch mit allen last_run_at/last_result-Updates.
return [outMessages.length > 0 ? outMessages : null, resultMsg];

// Unerwartete Fehler im Runner als Warnung loggen.
// Kein Re-Throw – Runner soll beim nächsten Tick erneut versuchen.
const errText = (msg.error && msg.error.message) || String(msg.error) || 'Unbekannter Fehler';
node.warn('Automation-Runner Fehler: ' + errText);
return null;
